import tools,torch
modules={'msvr_task_state_optimizer': '"""AdaTask-inspired supported R/A states; fixed FP32 AdamW contract.\n\nNo data/model code. Full current+historical R and direct A must be unscaled\nbefore step. Parameter gradients remain available for GradScaler\'s checks.\n"""\nimport torch\n\n\nclass SupportedTaskAdamW(torch.optim.Optimizer):\n    def __init__(self, parameters, role_parameters, *, split, lr, weight_decay):\n        parameters = list(parameters)\n        super().__init__(parameters, dict(lr=lr, weight_decay=weight_decay,\n                                         betas=(0.9, 0.999), eps=1e-8))\n        self.roles = list(role_parameters)\n        self.role_ids = {id(p): i for i, p in enumerate(self.roles)}\n        assert len(self.role_ids) == len(self.roles)\n        assert set(self.role_ids).issubset({id(p) for p in parameters})\n        assert all(p.dtype == torch.float32 for p in parameters)\n        self.split = bool(split)\n\n    @staticmethod\n    def direction(state, key, gradient, beta1, beta2, eps):\n        if key not in state:\n            state[key] = dict(step=0, exp_avg=torch.zeros_like(gradient),\n                              exp_avg_sq=torch.zeros_like(gradient))\n        task = state[key]\n        task[\'step\'] += 1\n        task[\'exp_avg\'].lerp_(gradient, 1-beta1)\n        task[\'exp_avg_sq\'].mul_(beta2).addcmul_(gradient, gradient, value=1-beta2)\n        denominator = task[\'exp_avg_sq\'].sqrt() / (1-beta2**task[\'step\'])**0.5\n        denominator.add_(eps)\n        return (task[\'exp_avg\'] / (1-beta1**task[\'step\'])) / denominator\n\n    @torch.no_grad()\n    def step(self, *, rank_gradients, auxiliary_gradients, rank_observed):\n        assert len(rank_gradients) == len(auxiliary_gradients) == len(self.roles)\n        for p, r, a in zip(self.roles, rank_gradients, auxiliary_gradients, strict=True):\n            assert r.shape == a.shape == p.shape\n            assert r.dtype == a.dtype == p.dtype\n            assert r.device == a.device == p.device\n            assert torch.isfinite(r).all() and torch.isfinite(a).all()\n            if not rank_observed:\n                assert not bool(r.abs().sum())\n        # Validate all gradients before mutating any parameter or task state.\n        for group in self.param_groups:\n            for p in group[\'params\']:\n                assert p.grad is not None and torch.isfinite(p.grad).all()\n        for group in self.param_groups:\n            beta1, beta2 = group[\'betas\']\n            for p in group[\'params\']:\n                state = self.state[p]\n                if id(p) in self.role_ids:\n                    i = self.role_ids[id(p)]\n                    r, a = rank_gradients[i], auxiliary_gradients[i]\n                    if self.split:\n                        update = self.direction(state, \'auxiliary\', a, beta1, beta2, group[\'eps\'])\n                        if rank_observed:\n                            update = update + self.direction(state, \'rank\', r, beta1, beta2, group[\'eps\'])\n                    else:\n                        update = self.direction(state, \'shared\', r+a, beta1, beta2, group[\'eps\'])\n                else:\n                    update = self.direction(state, \'head\', p.grad, beta1, beta2, group[\'eps\'])\n                p.mul_(1-group[\'lr\']*group[\'weight_decay\'])\n                p.add_(update, alpha=-group[\'lr\'])\n', 'msvr_task_state_records': '"""State witnesses and exact disk serialization checks for the new run only."""\nimport math\nimport torch\nfrom tools.train_msvr310_signal_oof import sha256\n\n\ndef task_state_summary(optimizer,parameters,groups):\n    result={}\n    for role,indexes in groups.items():\n        keys=set(optimizer.state[parameters[indexes[0]]])\n        assert all(set(optimizer.state[parameters[i]])==keys for i in indexes)\n        tasks={}\n        for key in sorted(keys):\n            states=[optimizer.state[parameters[i]][key] for i in indexes]\n            counts={s[\'step\'] for s in states};assert len(counts)==1\n            tasks[key]=dict(step=counts.pop(),\n                first_moment_norm=math.sqrt(sum(float(s[\'exp_avg\'].double().square().sum()) for s in states)),\n                second_moment_norm=math.sqrt(sum(float(s[\'exp_avg_sq\'].double().square().sum()) for s in states)))\n        result[role]=tasks\n    return result\n\n\ndef save_optimizer_state(optimizer,scaler,path,names,endpoint):\n    assert not path.exists()\n    original=optimizer.state_dict()\n    payload=dict(optimizer=original,scaler=scaler.state_dict(),parameter_names=names,endpoint=endpoint)\n    torch.save(payload,path)\n    loaded=torch.load(path,map_location=\'cpu\',weights_only=False)\n    assert loaded[\'parameter_names\']==names and loaded[\'endpoint\']==endpoint\n    assert loaded[\'scaler\']==scaler.state_dict()\n    assert loaded[\'optimizer\'][\'param_groups\']==original[\'param_groups\']\n    assert set(loaded[\'optimizer\'][\'state\'])==set(original[\'state\'])\n    count=0\n    for index,state in original[\'state\'].items():\n        restored=loaded[\'optimizer\'][\'state\'][index]\n        assert set(restored)==set(state)\n        for key,task in state.items():\n            assert restored[key][\'step\']==task[\'step\']\n            for moment in (\'exp_avg\',\'exp_avg_sq\'):\n                assert torch.equal(restored[key][moment],task[moment].cpu())\n                count+=1\n    optimizer.load_state_dict(loaded[\'optimizer\'])\n    scaler.load_state_dict(loaded[\'scaler\'])\n    current=optimizer.state_dict()\n    assert current[\'param_groups\']==loaded[\'optimizer\'][\'param_groups\']\n    for index,state in current[\'state\'].items():\n        for key,task in state.items():\n            assert task[\'step\']==loaded[\'optimizer\'][\'state\'][index][key][\'step\']\n            for moment in (\'exp_avg\',\'exp_avg_sq\'):\n                assert torch.equal(task[moment].cpu(),loaded[\'optimizer\'][\'state\'][index][key][moment])\n    return dict(path=str(path),bytes=path.stat().st_size,sha256=sha256(path),\n                endpoint=endpoint,parameter_count=len(names),moment_tensors_checked=count,\n                disk_payload_exact=True,reloaded_moments_exact=True,scaler_exact=True,\n                scope=\'Final state serialization/reload only; no extra model update or resumed training.\')\n', 'verify_msvr_task_state_records': '"""Replay support clocks and saved moments; not regenerated training gradients."""\nfrom pathlib import Path\nimport math\nimport torch\nfrom tools.train_msvr310_signal_oof import sha256\n\n\ndef verify_states(audits,tr,endpoint,warmup):\n    observed=0;previous=None;references=0\n    for i,audit in enumerate(audits):\n        ids=audit[\'identities\'];scenes=audit[\'scenes\']\n        candidates=list(zip(ids,scenes))+[(r[\'identity\'],r[\'scene\']) for r in audit[\'memory\']]\n        counts=[sum(y==identity and other_scene!=scene for y,other_scene in candidates)\n                for identity,scene in zip(ids,scenes,strict=True)]\n        assert counts==audit[\'relation_objective\'][\'cross_scene_positive_counts\']\n        positive_ids={identity for identity,n in zip(ids,counts,strict=True) if n>0}\n        relations={(identity,scene,other_scene) for identity,scene,n in zip(ids,scenes,counts,strict=True)\n                   if n>0 for y,other_scene in candidates if y==identity and other_scene!=scene}\n        expected=dict(eligible_anchors=sum(n>0 for n in counts),eligible_identities=len(positive_ids),\n                      identity_directed_scene_relations=len(relations))\n        assert audit[\'support\']==expected\n        wanted=i<warmup or expected[\'eligible_anchors\']>0\n        assert audit[\'rank_observed\']==wanted\n        observed+=int(wanted)\n        assert audit[\'direct_ra_assembly\'] and audit[\'classification_head_gradients_unchanged\']\n        assert audit[\'current_rank_backward_calls\']==audit[\'current_auxiliary_backward_calls\']==1\n        has_reference=bool(audit[\'direct_single_group_check\'])\n        assert bool(audit[\'rank_auxiliary_reference_checks\'])==has_reference\n        assert audit[\'direct_component_backward_calls\']==(4 if has_reference else 0)\n        assert set(audit[\'actual_parameter_updates\'])=={\'cnn\',\'transformer\',\'mamba\'}\n        if has_reference:\n            assert set(audit[\'rank_auxiliary_reference_checks\'])=={\'cnn\',\'transformer\',\'mamba\'}\n        states=audit[\'task_states\']\n        assert set(states)=={\'cnn\',\'transformer\',\'mamba\'}\n        for role,tasks in states.items():\n            from tools.verify_msvr_supported_gradient_balance_stats import pair\n            pair(audit[\'actual_parameter_updates\'][role])\n            keys={\'shared\'} if endpoint==\'control\' else {\'auxiliary\',\'rank\'} if observed else {\'auxiliary\'}\n            assert set(tasks)==keys\n            for key,task in tasks.items():\n                assert task[\'step\']==(observed if key==\'rank\' else i+1)\n                assert all(math.isfinite(task[k]) and task[k]>=0 for k in (\'first_moment_norm\',\'second_moment_norm\'))\n            if endpoint==\'split\' and not wanted and previous and \'rank\' in previous[role]:\n                assert tasks[\'rank\']==previous[role][\'rank\']\n            if audit[\'rank_auxiliary_reference_checks\']:\n                checks=audit[\'rank_auxiliary_reference_checks\'][role]\n                assert set(checks)=={\'current_rank\',\'historical_rank\',\'full_rank\',\'auxiliary\',\'assembled\'}\n                for check in checks.values():\n                    assert check[\'passed\']\n                    error=check[\'difference_norm\']/check[\'first_norm\'] if check[\'first_norm\'] else None\n                    assert error==check[\'relative_l2_error\']\n                    assert error<=.005 if error is not None else check[\'difference_norm\']<=1e-8\n                    references+=1\n        previous=states\n    assert references==(15 if tr[\'mode\']==\'capacity\' else 0)\n    assert tr[\'current_rank_backward_calls\']==tr[\'current_auxiliary_backward_calls\']==len(audits)\n    assert tr[\'direct_component_backward_calls\']==(4 if tr[\'mode\']==\'capacity\' else 0)\n    proof=tr[\'optimizer_state\'];path=Path(proof[\'path\'])\n    assert path.is_file() and sha256(path)==proof[\'sha256\'] and path.stat().st_size==proof[\'bytes\']\n    assert proof[\'disk_payload_exact\'] and proof[\'reloaded_moments_exact\'] and proof[\'scaler_exact\']\n    saved=torch.load(path,map_location=\'cpu\',weights_only=False)\n    names=saved[\'parameter_names\'];assert len(names)==len(set(names))==proof[\'parameter_count\']==203\n    assert saved[\'endpoint\']==endpoint and tr[\'task_state_split\']==(endpoint==\'split\')\n    state=saved[\'optimizer\'][\'state\'];groups=saved[\'optimizer\'][\'param_groups\']\n    assert len(groups)==1 and groups[0][\'params\']==list(range(203)) and set(state)==set(range(203))\n    role_rows={role:[] for role in previous};moment_tensors=0\n    for index,name in enumerate(names):\n        matched=[role for role in role_rows if name.startswith(\'encoder.\'+role+\'_\')]\n        keys=set(state[index])\n        if matched:\n            assert len(matched)==1;role=matched[0];role_rows[role].append(index)\n            assert keys==set(previous[role])\n        else:assert keys=={\'head\'}\n        for key,task in state[index].items():\n            assert task[\'step\']==(observed if key==\'rank\' else len(audits))\n            assert task[\'exp_avg\'].dtype==task[\'exp_avg_sq\'].dtype==torch.float32\n            assert task[\'exp_avg\'].shape==task[\'exp_avg_sq\'].shape\n            assert torch.isfinite(task[\'exp_avg\']).all() and torch.isfinite(task[\'exp_avg_sq\']).all()\n            assert (task[\'exp_avg_sq\']>=0).all();moment_tensors+=2\n    assert [len(role_rows[r]) for r in (\'cnn\',\'transformer\',\'mamba\')]==[42,54,93]\n    for role,indexes in role_rows.items():\n        for key,task in previous[role].items():\n            for field,moment in [(\'first_moment_norm\',\'exp_avg\'),(\'second_moment_norm\',\'exp_avg_sq\')]:\n                norm=math.sqrt(sum(float(state[i][key][moment].double().square().sum()) for i in indexes))\n                assert abs(norm-task[field])<=1e-9*max(1,norm)\n    assert moment_tensors==proof[\'moment_tensors_checked\']\n    assert saved[\'scaler\'][\'scale\']==tr[\'steps\'][-1][\'amp_scale_after\']\n    return dict(observed_rank_steps=observed,absent_rank_steps=len(audits)-observed,\n                moment_tensors=moment_tensors,direct_component_checks=references,\n                optimizer_state_sha256=proof[\'sha256\'],scope=\'Saved state and counters only; parameter-gradient trajectory not reconstructed.\')\n'}
for name,source in modules.items():
    module=types.ModuleType('tools.'+name);sys.modules[module.__name__]=module
    exec(compile(source,name,'exec'),module.__dict__)
from tools.msvr_task_state_optimizer import SupportedTaskAdamW
from tools.msvr_task_state_records import task_state_summary,save_optimizer_state
from tools.verify_msvr_task_state_records import verify_states
root=Path('/root/autodl-tmp/trifusion-v2/artifacts/task_state_serialization_synthetic_r2_20260921')
root.mkdir()
torch.manual_seed(42)
names=[f'encoder.{role}_fixture.p{i}' for role,n in [('cnn',42),('transformer',54),('mamba',93)] for i in range(n)]+[f'head.p{i}' for i in range(14)]
groups={role:[i for i,name in enumerate(names[:189]) if name.startswith('encoder.'+role+'_')] for role in ('cnn','transformer','mamba')}
results=[]
for split in (False,True):
    endpoint='split' if split else 'control'
    parameters=[torch.nn.Parameter(torch.randn(2)) for _ in names]
    roles=parameters[:189]
    opt=SupportedTaskAdamW(parameters,roles,split=split,lr=.0003,weight_decay=.01)
    scaler=torch.amp.GradScaler('cpu',init_scale=256.)
    scaler.scale(parameters[0].sum())
    audits=[]
    for step in range(4):
        observed=step!=1
        r=[torch.randn_like(p) if observed and step!=2 else torch.zeros_like(p) for p in roles]
        a=[torch.randn_like(p) for p in roles]
        for p in parameters:p.grad=torch.randn_like(p)
        for p,x,y in zip(roles,r,a):p.grad=x+y
        before=[p.detach().clone() for p in roles]
        opt.step(rank_gradients=r,auxiliary_gradients=a,rank_observed=observed)
        from tools.probe_msvr_history_candidate_gradients import compare
        updates={role:compare([before[i] for i in indexes],[roles[i].detach() for i in indexes]) for role,indexes in groups.items()}
        ids=['a','a','b'];scenes=['x','y' if observed else 'x','x']
        support=dict(eligible_anchors=2 if observed else 0,eligible_identities=int(observed),identity_directed_scene_relations=2 if observed else 0)
        audits.append(dict(support=support,rank_observed=observed,identities=ids,scenes=scenes,memory=[],
            relation_objective=dict(cross_scene_positive_counts=[1,1,0] if observed else [0,0,0]),
            direct_single_group_check={},direct_component_backward_calls=0,actual_parameter_updates=updates,
            direct_ra_assembly=True,classification_head_gradients_unchanged=True,
            current_rank_backward_calls=1,current_auxiliary_backward_calls=1,
            task_states=task_state_summary(opt,roles,groups),rank_auxiliary_reference_checks={}))
    proof=save_optimizer_state(opt,scaler,root/(endpoint+'.pt'),names,endpoint)
    tr=dict(optimizer_state=proof,task_state_split=split,steps=[dict(amp_scale_after=256.)]*4,
        mode='comparison',current_rank_backward_calls=4,current_auxiliary_backward_calls=4,direct_component_backward_calls=0)
    check=verify_states(audits,tr,endpoint,0)
    corrupted=copy.deepcopy(audits);corrupted[-1]['rank_observed']=False
    rejected=False
    try:verify_states(corrupted,tr,endpoint,0)
    except AssertionError:rejected=True
    assert rejected
    results.append(dict(endpoint=endpoint,proof=proof,check=check,corrupted_support_rejected=True))
assert not torch.cuda.is_initialized()
print(json.dumps(dict(status='PASS_SYNTHETIC_DISK_STATE_CHECK',results=results,
    cuda_initialized=False,model_forwards=0,training_updates=0,scope='203 small synthetic tensors, no TriFusion model or images'),indent=2))
